//! Section dividers as lossless line splices: insert (at the top or above a rule), rename and
//! remove a banner.
//!
//! A divider is never part of a block's span, so every operation here leaves the block ids and
//! their span texts unchanged and goes through [`Document::commit_structural`], which refuses the
//! edit (leaving the document untouched) if any span would differ. A banner is addressed by its
//! *ordinal*: its index in [`section::banners`] (the economy banner included). The economy banner
//! is generated by FerrisFilter and is never edited here.

use super::Document;
use super::block::BlockId;
use super::edit::EditError;
use super::group;
use super::lines::{Eol, Line};
use super::meta;
use super::section::{self, BannerKind};
use super::structure::is_blank;

impl Document {
    /// Ids and span texts of the current blocks, unchanged by a divider edit.
    fn unchanged_blocks(&self) -> (Vec<Option<BlockId>>, Vec<Vec<String>>) {
        let infos = self.infos();
        (
            infos.iter().map(|i| Some(i.id)).collect(),
            infos
                .iter()
                .map(|i| self.span_texts(i.span.clone()))
                .collect(),
        )
    }

    fn commit_unchanged(&mut self, new: Vec<Line>) -> Result<(), EditError> {
        let (ids, expected) = self.unchanged_blocks();
        self.commit_structural(new, ids, expected).map(|_| ())
    }

    /// The terminator for lines created before line `ins`.
    fn eol_before(&self, ins: usize) -> Eol {
        if ins > 0 {
            self.fresh_eol(ins - 1)
        } else {
            match self.lines.first().map(|l| l.eol()) {
                Some(e) if e != Eol::None => e,
                _ => self.last_eol(),
            }
        }
    }

    /// Insert a banner named `name` so that its first line is at old line `ins`, with one blank
    /// line on each side added only where missing. Returns the ordinal of the new banner.
    fn insert_banner_at(&mut self, ins: usize, name: &str) -> Result<usize, EditError> {
        let eol = self.eol_before(ins);
        let ordinal = section::banner_starts(&self.lines)
            .iter()
            .filter(|&&s| s < ins)
            .count();
        let at_end = ins >= self.lines.len();
        let unterminated_end = at_end && self.lines.last().is_some_and(|l| l.eol() == Eol::None);
        let mut new: Vec<Line> = self.lines[..ins].to_vec();
        if let Some(last) = new.last_mut() {
            if last.eol() == Eol::None {
                *last = Line::new(last.text().to_string(), eol);
            }
        }
        if new.last().is_some_and(|l| !is_blank(l)) {
            new.push(Line::new(String::new(), eol));
        }
        let middle = meta::ff_line(section::SECTION_KEY, Some(&section::sanitize_name(name)));
        for text in [section::RULE_LINE, middle.as_str(), section::RULE_LINE] {
            new.push(Line::new(text.to_string(), eol));
        }
        if unterminated_end {
            if let Some(l) = new.last_mut() {
                *l = Line::new(l.text().to_string(), Eol::None);
            }
        }
        if self.lines.get(ins).is_some_and(|l| !is_blank(l)) {
            new.push(Line::new(String::new(), eol));
        }
        new.extend_from_slice(&self.lines[ins..]);
        self.commit_unchanged(new)?;
        Ok(ordinal)
    }

    /// Insert a section divider at the same point `+ Add rule` uses: the top of the file, above
    /// the first rule or the first divider. Returns its ordinal (always 0).
    pub fn insert_section_at_top(&mut self, name: &str) -> Result<usize, EditError> {
        let sec = section::find(self).map_err(|e| EditError::EconomyDamaged(e.to_string()))?;
        let ins = self.top_insertion_line(sec);
        self.insert_banner_at(ins, name)
    }

    /// Insert a section divider directly above a rule (above the whole `# ff:group` run when the
    /// block belongs to one). Returns its ordinal.
    pub fn insert_section_above(&mut self, id: BlockId, name: &str) -> Result<usize, EditError> {
        let sec = section::find(self).map_err(|e| EditError::EconomyDamaged(e.to_string()))?;
        let infos = self.infos();
        let info = infos
            .iter()
            .find(|i| i.id == id)
            .ok_or(EditError::UnknownBlock)?;
        if sec.is_some_and(|s| info.header > s.begin && info.header < s.end) {
            return Err(EditError::SectionLocked);
        }
        let g = group::analyze(self);
        let first = g.members(g.rule_of(id))[0];
        let ins = infos
            .iter()
            .find(|i| i.id == first)
            .ok_or(EditError::UnknownBlock)?
            .span
            .start;
        self.insert_banner_at(ins, name)
    }

    /// The user (non-economy) banner at `ordinal`: its first line.
    fn user_banner(&self, ordinal: usize) -> Result<usize, EditError> {
        let b = section::banners(self);
        let b = b.get(ordinal).ok_or(EditError::UnknownSection)?;
        if b.kind == BannerKind::Economy {
            return Err(EditError::SectionLocked);
        }
        Ok(b.start)
    }

    /// Rewrite only the banner's middle line to `# ff:section <name>`, keeping its line ending.
    pub fn rename_section(&mut self, ordinal: usize, name: &str) -> Result<(), EditError> {
        let start = self.user_banner(ordinal)?;
        let mid = start + 1;
        let text = meta::ff_line(section::SECTION_KEY, Some(&section::sanitize_name(name)));
        let mut new = self.lines.clone();
        new[mid] = Line::new(text, self.lines[mid].eol());
        self.commit_unchanged(new)
    }

    /// Delete the banner (its rules stay) and one adjacent blank line: the one below if present,
    /// else the one above.
    pub fn remove_section(&mut self, ordinal: usize) -> Result<(), EditError> {
        let start = self.user_banner(ordinal)?;
        let mut from = start;
        let mut to = start + 3;
        if self.lines.get(to).is_some_and(is_blank) {
            to += 1;
        } else if from > 0 && is_blank(&self.lines[from - 1]) {
            from -= 1;
        }
        let ends_file = to >= self.lines.len();
        let unterminated = ends_file && self.lines.last().is_some_and(|l| l.eol() == Eol::None);
        let mut new = self.lines[..from].to_vec();
        new.extend_from_slice(&self.lines[to..]);
        if unterminated {
            if let Some(l) = new.last_mut() {
                *l = Line::new(l.text().to_string(), Eol::None);
            }
        }
        self.commit_unchanged(new)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::filter::parse;

    const R: &str = section::RULE_LINE;

    fn p(s: &str) -> Document {
        parse(s.as_bytes()).unwrap()
    }

    #[test]
    fn insert_at_top_basic() {
        let mut d = p("Show\n\tRarity Rare\n");
        assert_eq!(d.insert_section_at_top("Leveling").unwrap(), 0);
        assert_eq!(
            d.serialize(),
            format!("{R}\n# ff:section Leveling\n{R}\n\nShow\n\tRarity Rare\n")
        );
    }

    #[test]
    fn insert_at_top_after_title_comment() {
        let mut d = p("# My filter\n\nShow\n");
        d.insert_section_at_top("A").unwrap();
        assert_eq!(
            d.serialize(),
            format!("# My filter\n\n{R}\n# ff:section A\n{R}\n\nShow\n")
        );
    }

    #[test]
    fn insert_at_top_above_existing_banner() {
        let mut d = p(&format!("{R}\n# ff:section Old\n{R}\n\nShow\n"));
        assert_eq!(d.insert_section_at_top("New").unwrap(), 0);
        assert_eq!(
            d.serialize(),
            format!("{R}\n# ff:section New\n{R}\n\n{R}\n# ff:section Old\n{R}\n\nShow\n")
        );
        assert_eq!(section::banners(&d)[1].name, "Old");
    }

    #[test]
    fn insert_above_a_rule_and_remove_restores() {
        let src = "Show\n\nHide\n\n# ff:name three\nShow\n";
        let mut d = p(src);
        let third = d.blocks().nth(2).unwrap().id();
        let k = d.insert_section_above(third, "X").unwrap();
        assert_eq!(k, 0);
        assert_eq!(
            d.serialize(),
            format!("Show\n\nHide\n\n{R}\n# ff:section X\n{R}\n\n# ff:name three\nShow\n")
        );
        d.remove_section(k).unwrap();
        assert_eq!(d.serialize(), src);
    }

    #[test]
    fn insert_above_without_blank_adds_both() {
        let mut d = p("Show\nHide\n");
        let second = d.blocks().nth(1).unwrap().id();
        d.insert_section_above(second, "X").unwrap();
        assert_eq!(
            d.serialize(),
            format!("Show\n\n{R}\n# ff:section X\n{R}\n\nHide\n")
        );
    }

    #[test]
    fn insert_above_group_follower_lands_above_the_run() {
        let src = "# ff:group abc123 1/2\nShow\n\tBaseArmour > 0\n\n# ff:group abc123 2/2\nShow\n\tBaseArmour > 0\n";
        let mut d = p(src);
        let g0 = group::analyze(&d);
        let ids: Vec<_> = d.blocks().map(|b| b.id()).collect();
        assert_eq!(g0.members(ids[0]).len(), 2, "fixture is a valid run");
        d.insert_section_above(ids[1], "G").unwrap();
        assert_eq!(d.serialize(), format!("{R}\n# ff:section G\n{R}\n\n{src}"));
        let g = group::analyze(&d);
        assert_eq!(g.members(ids[0]).len(), 2);
    }

    #[test]
    fn insert_above_economy_block_is_locked() {
        let src = format!(
            "Show\n\n{R}\n{}\n{R}\n\nShow\n\tClass \"Rings\"\n",
            section::BEGIN_LINE
        );
        let mut d = p(&src);
        let eco = d.blocks().nth(1).unwrap().id();
        assert!(matches!(
            d.insert_section_above(eco, "X").unwrap_err(),
            EditError::SectionLocked
        ));
        assert_eq!(d.serialize(), src);
    }

    #[test]
    fn rename_rewrites_only_the_middle_line() {
        let src = format!("{R}\r\n#ff:section Old\r\n{R}\r\n\r\nShow\r\n");
        let mut d = p(&src);
        d.rename_section(0, "  End\ngame  ").unwrap();
        assert_eq!(
            d.serialize(),
            format!("{R}\r\n# ff:section End game\r\n{R}\r\n\r\nShow\r\n")
        );
        d.rename_section(0, "   ").unwrap();
        assert!(d.serialize().contains("# ff:section Section\r\n"));
        assert!(matches!(
            d.rename_section(5, "x").unwrap_err(),
            EditError::UnknownSection
        ));
    }

    #[test]
    fn rename_cannot_inject_a_rule() {
        let mut d = p(&format!("{R}\n# ff:section A\n{R}\n\nShow\n"));
        d.rename_section(0, "x\nShow").unwrap();
        assert_eq!(d.blocks().count(), 1);
        assert!(d.serialize().contains("# ff:section x Show\n"));
    }

    #[test]
    fn economy_banner_is_locked() {
        let src = format!("Show\n\n{R}\n{}\n{R}\n\nShow\n", section::BEGIN_LINE);
        let mut d = p(&src);
        assert!(matches!(
            d.rename_section(0, "x").unwrap_err(),
            EditError::SectionLocked
        ));
        assert!(matches!(
            d.remove_section(0).unwrap_err(),
            EditError::SectionLocked
        ));
        assert_eq!(d.serialize(), src);
    }

    #[test]
    fn remove_takes_blank_above_when_none_below() {
        let mut d = p(&format!("Show\n\n{R}\n# ff:section A\n{R}\nHide\n"));
        d.remove_section(0).unwrap();
        assert_eq!(d.serialize(), "Show\nHide\n");
    }

    #[test]
    fn identity_for_crlf_and_unterminated_last_line() {
        for src in [
            "Show\r\n\r\nHide\r\n",
            "Show\n\nHide",
            "Show\n\nHide\n",
            "Show",
        ] {
            let mut d = p(src);
            let ids: Vec<_> = d.blocks().map(|b| b.id()).collect();
            let k = d.insert_section_above(*ids.last().unwrap(), "A").unwrap();
            d.remove_section(k).unwrap();
            assert_eq!(d.serialize(), src, "above {src:?}");
            assert_eq!(d.blocks().map(|b| b.id()).collect::<Vec<_>>(), ids);
            let k = d.insert_section_at_top("T").unwrap();
            d.remove_section(k).unwrap();
            assert_eq!(d.serialize(), src, "top {src:?}");
        }
    }

    #[test]
    fn insert_into_empty_blocks_file() {
        for src in ["", "# only a comment", "# only a comment\n"] {
            let mut d = p(src);
            let k = d.insert_section_at_top("A").unwrap();
            d.remove_section(k).unwrap();
            assert_eq!(d.serialize(), src);
        }
    }
}
